/* =====================================================================
   PORTFÓLIO — seção "O que seu site pode ter?"
   Renderiza os cards a partir de PORTFOLIO.possibilidades, liga as
   demonstrações (modelos 3D em GLB, vídeos, parallax do cursor, holofote) e a seleção
   "+ Quero isso", que alimenta o formulário de ideia no contato.
   Carregado antes de main.js para que os reveals sejam observados.
   ===================================================================== */
(function () {
  'use strict';
  // Modelos 3D embutidos como base64: abrir o arquivo direto (file://) bloqueia o fetch
  // de arquivos externos por segurança do navegador, então incorporamos os GLB aqui,
  // do mesmo jeito que o bundle three-scenes.bundle.js faz com o dragão e os ícones do Office.
  const MODEL_CADEADO = 'data:model/gltf-binary;base64,';
  const MODEL_LATAS = 'data:model/gltf-binary;base64,';
  const P = window.PORTFOLIO && window.PORTFOLIO.possibilidades;
  const grid = document.getElementById('possGrid');
  if (!P || !grid) return;

  const $ = (s, r = document) => r.querySelector(s);
  const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  const esc = (s) => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

  /* ---------- QR ilustrativo (padrão fixo, não é um código real) ---------- */
  const qrSvg = (() => {
    const n = 13; let seed = 7; const rnd = () => (seed = (seed * 16807) % 2147483647) / 2147483647;
    let d = '';
    const finder = (x, y) => { for (let i = 0; i < 5; i++) for (let j = 0; j < 5; j++) { if (i === 0 || i === 4 || j === 0 || j === 4 || (i === 2 && j === 2)) d += `M${x + j} ${y + i}h1v1h-1z`; } };
    finder(0, 0); finder(8, 0); finder(0, 8);
    for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
      const inFinder = (x < 6 && y < 6) || (x >= 7 && y < 6) || (x < 6 && y >= 7);
      if (!inFinder && rnd() < 0.42) d += `M${x} ${y}h1v1h-1z`;
    }
    return `<svg viewBox="0 0 ${n} ${n}" aria-hidden="true"><path d="${d}"/></svg>`;
  })();

  /* ---------- Demonstrações visuais por card ---------- */
  const demos = {
    'identidade': `<div class="pd pd-identity" aria-hidden="true">
        <div class="pd-identity__browser">
          <span class="pd-identity__bar"><i></i><i></i><i></i></span>
          <div class="pd-identity__screen"><img src="assets/img/possibilidades/identidade.webp" alt="" width="736" height="1318" loading="lazy"></div>
        </div>
        <div class="pd-identity__side">
          <span class="pd-identity__type"><em>Aa</em><b>Aa</b></span>
          <span class="pd-identity__swatches"><i></i><i></i><i></i><i></i></span>
          <span class="pd-identity__note mono">Passe o mouse para rolar o site</span>
        </div>
      </div>`,
    '3d': `<div class="pd pd-model pd-model--split" aria-hidden="true" data-model="LATAS" data-spin="0.35" data-fit="1.55">
        <video class="pd-model__video" src="assets/video/3d-preview.mp4" muted loop playsinline preload="metadata" data-autoplay></video>
        <canvas class="pd-model__canvas"></canvas>
        <span class="pd-model__hint mono">Arraste para girar</span>
      </div>`,
    'video': `<div class="pd pd-film" aria-hidden="true">
        <div class="pd-film__frame">
          <span class="pd-film__scene"></span>
          <video class="pd-film__video" src="assets/video/cinema.mp4" muted loop playsinline preload="metadata" data-autoplay></video>
          <span class="pd-film__tc mono">16:9 · loop · sem áudio</span>
        </div>
      </div>`,
    'pagamentos': `<div class="pd pd-pay" aria-hidden="true">
        <div class="pd-pay__card">
          <span class="pd-pay__qr">${qrSvg}</span>
          <span class="pd-pay__info"><b>Pedido #0421</b><small class="mono">PIX · R$ 149,90</small></span>
          <span class="pd-pay__btn"><span>Pagar agora</span><span>✓ Pagamento confirmado</span></span>
        </div>
      </div>`,
    'area-cliente': `<div class="pd pd-portal" aria-hidden="true">
        <div class="pd-portal__win">
          <span class="pd-portal__head"><i class="pd-portal__avatar"></i><b>Olá, Ana</b><small class="mono">Área do cliente</small></span>
          <span class="pd-portal__row"><em>Pedido #1042</em><small class="mono">Em produção</small><i style="--w:64%"></i></span>
          <span class="pd-portal__row"><em>Pedido #1037</em><small class="mono">Entregue</small><i style="--w:100%"></i></span>
        </div>
      </div>`,
    'dados': `<div class="pd pd-model pd-model--lock" aria-hidden="true" data-model="CADEADO" data-spin="0.28" data-fit="1.75">
        <div class="pd-model__fallback pd-db"><div class="pd-db__stack"><i></i><i></i><i></i></div></div>
        <canvas class="pd-model__canvas"></canvas>
        <ul class="pd-db__tags mono"><li>Clientes <b>1.248</b></li><li>Produtos <b>214</b></li><li>Pedidos <b>3.910</b></li></ul>
        <span class="pd-model__hint mono">Arraste para girar</span>
      </div>`,
    'editorial': `<div class="pd pd-editorial" aria-hidden="true">
        <span class="pd-editorial__ghost">Fora</span>
        <span class="pd-editorial__solid">do óbvio</span>
        <img class="pd-editorial__img" src="assets/img/possibilidades/fora-do-obvio.webp" alt="" loading="lazy">
        <span class="pd-editorial__block"></span>
      </div>`,
    'conversao': `<div class="pd pd-funnel" aria-hidden="true">
        <span class="pd-funnel__step"><b>01</b>Atenção</span>
        <span class="pd-funnel__step"><b>02</b>Interesse</span>
        <span class="pd-funnel__step pd-funnel__step--cta"><b>03</b>Ação<i class="pd-funnel__btn">Chamar no WhatsApp</i></span>
      </div>`,
  };

  /* ---------- Render ---------- */
  grid.innerHTML = P.itens.map((it, i) => `<article class="poss-card poss-card--${it.id}" data-id="${esc(it.id)}" data-reveal style="--d:${(i % 3) * 70}ms">
      ${demos[it.id] || ''}
      <div class="poss-card__body">
        <span class="poss-card__n mono">${String(i + 1).padStart(2, '0')}</span>
        <h3 class="poss-card__title">${esc(it.titulo)}</h3>
        <p class="poss-card__text">${esc(it.texto)}</p>
        ${it.ideal ? `<p class="poss-card__ideal"><span class="mono">Ideal para</span> ${esc(it.ideal)}</p>` : ''}
        <div class="poss-card__foot">
          ${it.tags && it.tags.length ? `<ul class="poss-card__tags">${it.tags.map(t => `<li>${esc(t)}</li>`).join('')}</ul>` : '<span></span>'}
          <button class="poss-card__want mono" type="button" aria-pressed="false" aria-label="${esc(P.querer.marcar)}: ${esc(it.titulo)}"><span>${esc(P.querer.marcar)}</span></button>
        </div>
      </div>
    </article>`).join('');

  /* ---------- Holofote e parallax: posição do cursor dentro de cada card ---------- */
  grid.addEventListener('pointermove', (e) => {
    const card = e.target.closest('.poss-card'); if (!card) return;
    const r = card.getBoundingClientRect();
    card.style.setProperty('--mx', ((e.clientX - r.left) / r.width).toFixed(3));
    card.style.setProperty('--my', ((e.clientY - r.top) / r.height).toFixed(3));
  });
  grid.addEventListener('pointerleave', () => grid.querySelectorAll('.poss-card').forEach(c => { c.style.removeProperty('--mx'); c.style.removeProperty('--my'); }), true);

  /* ---------- Vídeos: só tocam quando o card está visível ---------- */
  grid.querySelectorAll('video[data-autoplay]').forEach((v) => {
    if (reduced) return;
    new IntersectionObserver(([en]) => { if (en.isIntersecting) v.play().catch(() => {}); else v.pause(); }, { rootMargin: '120px 0px' }).observe(v);
  });

  /* ---------- Modelos 3D (GLB): giram sozinhos e respondem ao arraste ---------- */
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  function initModels() {
    const T = window.PORTFOLIO_THREE; if (!T || !T.hasWebGL()) return;
    const { THREE, GLTFLoader } = T;
    grid.querySelectorAll('.pd-model').forEach((area) => {
      const canvas = area.querySelector('.pd-model__canvas'); if (!canvas) return;
      const renderer = new THREE.WebGLRenderer({ canvas, alpha: true, antialias: true, powerPreference: 'low-power' });
      renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
      renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.05;
      const scene = new THREE.Scene();
      const camera = new THREE.PerspectiveCamera(30, 1, 0.1, 50); camera.position.set(0, 0.25, 4.9); camera.lookAt(0, 0, 0);
      scene.add(new THREE.HemisphereLight(0xfff3ea, 0x1a120e, 1.2));
      const key = new THREE.DirectionalLight(0xffffff, 2.4); key.position.set(2.5, 3, 3); scene.add(key);
      const rim = new THREE.DirectionalLight(0xff5a2d, 1.8); rim.position.set(-3, 1.2, -2); scene.add(rim);
      const pivot = new THREE.Group(); scene.add(pivot);
      const spin = +(area.dataset.spin || 0.3);
      let rx = 0.22, ry = 0.7, vx = 0, vy = 0, drag = null, visible = false, ready = false;
      const modelUrl = area.dataset.model === 'CADEADO' ? MODEL_CADEADO : area.dataset.model === 'LATAS' ? MODEL_LATAS : area.dataset.model;
      new GLTFLoader().load(modelUrl, (g) => {
        const m = g.scene; const box = new THREE.Box3().setFromObject(m);
        const size = box.getSize(new THREE.Vector3()); const c = box.getCenter(new THREE.Vector3());
        m.position.sub(c); m.scale.setScalar((+area.dataset.fit || 2.1) / Math.max(size.x, size.y, size.z));
        pivot.add(m); ready = true; area.classList.add('is-ready');
      }, undefined, () => { /* mantém a prévia */ });
      new IntersectionObserver(([en]) => { visible = en.isIntersecting; }, { rootMargin: '80px 0px' }).observe(area);
      area.addEventListener('pointerdown', (e) => { drag = { x: e.clientX, y: e.clientY }; vx = vy = 0; area.classList.add('is-dragging'); try { area.setPointerCapture(e.pointerId); } catch (_) {} });
      area.addEventListener('pointermove', (e) => {
        if (!drag) return;
        vy = (e.clientX - drag.x) * 0.008; vx = (e.clientY - drag.y) * 0.008; drag = { x: e.clientX, y: e.clientY };
        ry += vy; rx = clamp(rx + vx, -1.2, 1.2);
      });
      const end = () => { drag = null; area.classList.remove('is-dragging'); };
      area.addEventListener('pointerup', end); area.addEventListener('pointercancel', end);
      function resize() {
        const w = canvas.clientWidth, h = canvas.clientHeight; if (!w || !h) return;
        if (canvas.width !== Math.round(w * renderer.getPixelRatio()) || canvas.height !== Math.round(h * renderer.getPixelRatio())) {
          renderer.setSize(w, h, false); camera.aspect = w / h; camera.updateProjectionMatrix();
        }
      }
      let last = performance.now();
      (function loop(now) {
        requestAnimationFrame(loop);
        const dt = Math.min(0.05, (now - last) / 1000); last = now;
        if (!visible || !ready) return;
        if (!drag) { vy *= 0.92; vx *= 0.92; ry += (reduced ? 0 : spin * dt) + vy; rx = clamp(rx + vx, -1.2, 1.2); }
        pivot.rotation.set(rx, ry, 0); resize(); renderer.render(scene, camera);
      })(last);
    });
  }
  if (window.PORTFOLIO_THREE) initModels(); else window.addEventListener('portfolio:three-ready', initModels, { once: true });

  /* ---------- Seleção "+ Quero isso" ---------- */
  const picked = new Set();
  const pickedNames = () => P.itens.filter(it => picked.has(it.id)).map(it => it.titulo);
  const pickedEl = $('#possPicked');
  function updatePicked() {
    const names = pickedNames();
    pickedEl.textContent = names.length ? `${names.length} ${names.length === 1 ? 'recurso escolhido' : 'recursos escolhidos'}: ${names.join(', ')}` : P.cta.vazio;
    pickedEl.classList.toggle('has-picks', names.length > 0);
  }
  grid.addEventListener('click', (e) => {
    const btn = e.target.closest('.poss-card__want'); if (!btn) return;
    const card = btn.closest('.poss-card'); const id = card.dataset.id;
    const on = !picked.has(id); if (on) picked.add(id); else picked.delete(id);
    card.classList.toggle('is-picked', on);
    btn.setAttribute('aria-pressed', String(on));
    btn.querySelector('span').textContent = on ? P.querer.marcado : P.querer.marcar;
    updatePicked();
  });
  updatePicked();

  // CTA final: leva as escolhas para o formulário do contato
  $('#possCta').addEventListener('click', () => {
    const ta = $('#ideaMessage'); const names = pickedNames();
    if (ta && names.length) {
      const prefix = P.cta.prefixo;
      const rest = ta.value.replace(new RegExp('^' + prefix.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '[^\n]*\n*'), '');
      ta.value = `${prefix} ${names.join(', ')}.\n\n${rest}`.trimEnd() + (rest.trim() ? '' : '\n\n');
    }
    const contato = $('#contato'); if (contato) contato.scrollIntoView({ behavior: reduced ? 'auto' : 'smooth' });
    if (ta) setTimeout(() => ta.focus({ preventScroll: true }), reduced ? 0 : 700);
  });

  // exposto para o envio pelo WhatsApp (main.js)
  window.PORTFOLIO_PICKS = pickedNames;
})();
